   209	/**
   210	 * DICT_FREE:
   211	 * @str:  a string
   212	 *
   213	 * Free a string if it is not owned by the "dict" dictionary in the
   214	 * current scope
   215	 */
   216	#define DICT_FREE(str)                                          \
   217	        if ((str) && ((!dict) ||                                \
   218	            (xmlDictOwns(dict, (const xmlChar *)(str)) == 0)))  \
   219	            xmlFree((char *)(str));
