   280	/**
   281	 * xmlTextReaderFreeProp:
   282	 * @reader:  the xmlTextReaderPtr used
   283	 * @cur:  the node
   284	 *
   285	 * Free a node.
   286	 */
   287	static void
   288	xmlTextReaderFreeProp(xmlTextReaderPtr reader, xmlAttrPtr cur) {
   289	    xmlDictPtr dict;
   290	
   291	    if ((reader != NULL) && (reader->ctxt != NULL))
   292	        dict = reader->ctxt->dict;
   293	    else
   294	        dict = NULL;
   295	    if (cur == NULL) return;
   296	
   297	    if ((__xmlRegisterCallbacks) && (xmlDeregisterNodeDefaultValue))
   298	        xmlDeregisterNodeDefaultValue((xmlNodePtr) cur);
   299	
   300	    /* Check for ID removal -> leading to invalid references ! */
   301	    if ((cur->parent != NULL) && (cur->parent->doc != NULL) &&
   302	        ((cur->parent->doc->intSubset != NULL) ||
   303	         (cur->parent->doc->extSubset != NULL))) {
   304	        if (xmlIsID(cur->parent->doc, cur->parent, cur))
   305	            xmlTextReaderRemoveID(cur->parent->doc, cur);
   306	    }
   307	    if (cur->children != NULL)
   308	        xmlTextReaderFreeNodeList(reader, cur->children);
   309	
   310	    DICT_FREE(cur->name);
   311	    if ((reader != NULL) && (reader->ctxt != NULL) &&
   312	        (reader->ctxt->freeAttrsNr < 100)) {
   313	        cur->next = reader->ctxt->freeAttrs;
   314	        reader->ctxt->freeAttrs = cur;
   315	        reader->ctxt->freeAttrsNr++;
   316	    } else {
   317	        xmlFree(cur);
   318	    }
   319	}
