   321	/**
   322	 * xmlTextReaderFreePropList:
   323	 * @reader:  the xmlTextReaderPtr used
   324	 * @cur:  the first property in the list
   325	 *
   326	 * Free a property and all its siblings, all the children are freed too.
   327	 */
   328	static void
   329	xmlTextReaderFreePropList(xmlTextReaderPtr reader, xmlAttrPtr cur) {
   330	    xmlAttrPtr next;
   331	
   332	    while (cur != NULL) {
   333	        next = cur->next;
   334	        xmlTextReaderFreeProp(reader, cur);
   335	        cur = next;
   336	    }
   337	}
