   339	/**
   340	 * xmlTextReaderFreeNodeList:
   341	 * @reader:  the xmlTextReaderPtr used
   342	 * @cur:  the first node in the list
   343	 *
   344	 * Free a node and all its siblings, this is a recursive behaviour, all
   345	 * the children are freed too.
   346	 */
   347	static void
   348	xmlTextReaderFreeNodeList(xmlTextReaderPtr reader, xmlNodePtr cur) {
   349	    xmlNodePtr next;
   350	    xmlDictPtr dict;
   351	
   352	    if ((reader != NULL) && (reader->ctxt != NULL))
   353	        dict = reader->ctxt->dict;
   354	    else
   355	        dict = NULL;
   356	    if (cur == NULL) return;
   357	    if (cur->type == XML_NAMESPACE_DECL) {
   358	        xmlFreeNsList((xmlNsPtr) cur);
   359	        return;
   360	    }
   361	    if ((cur->type == XML_DOCUMENT_NODE) ||
   362	        (cur->type == XML_HTML_DOCUMENT_NODE)) {
   363	        xmlFreeDoc((xmlDocPtr) cur);
   364	        return;
   365	    }
   366	    while (cur != NULL) {
   367	        next = cur->next;
   368	        /* unroll to speed up freeing the document */
   369	        if (cur->type != XML_DTD_NODE) {
   370	
   371	            if ((cur->children != NULL) &&
   372	                (cur->type != XML_ENTITY_REF_NODE)) {
   373	                if (cur->children->parent == cur)
   374	                    xmlTextReaderFreeNodeList(reader, cur->children);
   375	                cur->children = NULL;
   376	            }
   377	
   378	            if ((__xmlRegisterCallbacks) && (xmlDeregisterNodeDefaultValue))
   379	                xmlDeregisterNodeDefaultValue(cur);
   380	
   381	            if (((cur->type == XML_ELEMENT_NODE) ||
   382	                 (cur->type == XML_XINCLUDE_START) ||
   383	                 (cur->type == XML_XINCLUDE_END)) &&
   384	                (cur->properties != NULL))
   385	                xmlTextReaderFreePropList(reader, cur->properties);
   386	            if ((cur->content != (xmlChar *) &(cur->properties)) &&
   387	                (cur->type != XML_ELEMENT_NODE) &&
   388	                (cur->type != XML_XINCLUDE_START) &&
   389	                (cur->type != XML_XINCLUDE_END) &&
   390	                (cur->type != XML_ENTITY_REF_NODE)) {
   391	                DICT_FREE(cur->content);
   392	            }
   393	            if (((cur->type == XML_ELEMENT_NODE) ||
   394	                 (cur->type == XML_XINCLUDE_START) ||
   395	                 (cur->type == XML_XINCLUDE_END)) &&
   396	                (cur->nsDef != NULL))
   397	                xmlFreeNsList(cur->nsDef);
   398	
   399	            /*
   400	             * we don't free element names here they are interned now
   401	             */
   402	            if ((cur->type != XML_TEXT_NODE) &&
   403	                (cur->type != XML_COMMENT_NODE))
   404	                DICT_FREE(cur->name);
   405	            if (((cur->type == XML_ELEMENT_NODE) ||
   406	                 (cur->type == XML_TEXT_NODE)) &&
   407	                (reader != NULL) && (reader->ctxt != NULL) &&
   408	                (reader->ctxt->freeElemsNr < 100)) {
   409	                cur->next = reader->ctxt->freeElems;
   410	                reader->ctxt->freeElems = cur;
   411	                reader->ctxt->freeElemsNr++;
   412	            } else {
   413	                xmlFree(cur);
   414	            }
   415	        }
   416	        cur = next;
   417	    }
   418	}
