   420	/**
   421	 * xmlTextReaderFreeNode:
   422	 * @reader:  the xmlTextReaderPtr used
   423	 * @cur:  the node
   424	 *
   425	 * Free a node, this is a recursive behaviour, all the children are freed too.
   426	 * This doesn't unlink the child from the list, use xmlUnlinkNode() first.
   427	 */
   428	static void
   429	xmlTextReaderFreeNode(xmlTextReaderPtr reader, xmlNodePtr cur) {
   430	    xmlDictPtr dict;
   431	
   432	    if ((reader != NULL) && (reader->ctxt != NULL))
   433	        dict = reader->ctxt->dict;
   434	    else
   435	        dict = NULL;
   436	    if (cur->type == XML_DTD_NODE) {
   437	        xmlFreeDtd((xmlDtdPtr) cur);
   438	        return;
   439	    }
   440	    if (cur->type == XML_NAMESPACE_DECL) {
   441	        xmlFreeNs((xmlNsPtr) cur);
   442	        return;
   443	    }
   444	    if (cur->type == XML_ATTRIBUTE_NODE) {
   445	        xmlTextReaderFreeProp(reader, (xmlAttrPtr) cur);
   446	        return;
   447	    }
   448	
   449	    if ((cur->children != NULL) &&
   450	        (cur->type != XML_ENTITY_REF_NODE)) {
   451	        if (cur->children->parent == cur)
   452	            xmlTextReaderFreeNodeList(reader, cur->children);
   453	        cur->children = NULL;
   454	    }
   455	
   456	    if ((__xmlRegisterCallbacks) && (xmlDeregisterNodeDefaultValue))
   457	        xmlDeregisterNodeDefaultValue(cur);
   458	
   459	    if (((cur->type == XML_ELEMENT_NODE) ||
   460	         (cur->type == XML_XINCLUDE_START) ||
   461	         (cur->type == XML_XINCLUDE_END)) &&
   462	        (cur->properties != NULL))
   463	        xmlTextReaderFreePropList(reader, cur->properties);
   464	    if ((cur->content != (xmlChar *) &(cur->properties)) &&
   465	        (cur->type != XML_ELEMENT_NODE) &&
   466	        (cur->type != XML_XINCLUDE_START) &&
   467	        (cur->type != XML_XINCLUDE_END) &&
   468	        (cur->type != XML_ENTITY_REF_NODE)) {
   469	        DICT_FREE(cur->content);
   470	    }
   471	    if (((cur->type == XML_ELEMENT_NODE) ||
   472	         (cur->type == XML_XINCLUDE_START) ||
   473	         (cur->type == XML_XINCLUDE_END)) &&
   474	        (cur->nsDef != NULL))
   475	        xmlFreeNsList(cur->nsDef);
   476	
   477	    /*
   478	     * we don't free names here they are interned now
   479	     */
   480	    if ((cur->type != XML_TEXT_NODE) &&
   481	        (cur->type != XML_COMMENT_NODE))
   482	        DICT_FREE(cur->name);
   483	
   484	    if (((cur->type == XML_ELEMENT_NODE) ||
   485	         (cur->type == XML_TEXT_NODE)) &&
   486	        (reader != NULL) && (reader->ctxt != NULL) &&
   487	        (reader->ctxt->freeElemsNr < 100)) {
   488	        cur->next = reader->ctxt->freeElems;
   489	        reader->ctxt->freeElems = cur;
   490	        reader->ctxt->freeElemsNr++;
   491	    } else {
   492	        xmlFree(cur);
   493	    }
   494	}
