   501	/**
   502	 * xmlTextReaderFreeIDTable:
   503	 * @table:  An id table
   504	 *
   505	 * Deallocate the memory used by an ID hash table.
   506	 */
   507	static void
   508	xmlTextReaderFreeIDTable(xmlIDTablePtr table) {
   509	    xmlHashFree(table, xmlTextReaderFreeIDTableEntry);
   510	}
