   512	/**
   513	 * xmlTextReaderFreeDoc:
   514	 * @reader:  the xmlTextReaderPtr used
   515	 * @cur:  pointer to the document
   516	 *
   517	 * Free up all the structures used by a document, tree included.
   518	 */
   519	static void
   520	xmlTextReaderFreeDoc(xmlTextReaderPtr reader, xmlDocPtr cur) {
   521	    xmlDtdPtr extSubset, intSubset;
   522	
   523	    if (cur == NULL) return;
   524	
   525	    if ((__xmlRegisterCallbacks) && (xmlDeregisterNodeDefaultValue))
   526	        xmlDeregisterNodeDefaultValue((xmlNodePtr) cur);
   527	
   528	    /*
   529	     * Do this before freeing the children list to avoid ID lookups
   530	     */
   531	    if (cur->ids != NULL) xmlTextReaderFreeIDTable((xmlIDTablePtr) cur->ids);
   532	    cur->ids = NULL;
   533	    if (cur->refs != NULL) xmlFreeRefTable((xmlRefTablePtr) cur->refs);
   534	    cur->refs = NULL;
   535	    extSubset = cur->extSubset;
   536	    intSubset = cur->intSubset;
   537	    if (intSubset == extSubset)
   538	        extSubset = NULL;
   539	    if (extSubset != NULL) {
   540	        xmlUnlinkNode((xmlNodePtr) cur->extSubset);
   541	        cur->extSubset = NULL;
   542	        xmlFreeDtd(extSubset);
   543	    }
   544	    if (intSubset != NULL) {
   545	        xmlUnlinkNode((xmlNodePtr) cur->intSubset);
   546	        cur->intSubset = NULL;
   547	        xmlFreeDtd(intSubset);
   548	    }
   549	
   550	    if (cur->children != NULL) xmlTextReaderFreeNodeList(reader, cur->children);
